// Shared navigation for listening, singing and the community on desktop and mobile.
function updateBrowseNavigation(base,param){
 const primary=['karaoke','sing','cover'].includes(base)?'karaoke':['community','covers','crew','producer','artist','following'].includes(base)?'community':base==='dm'?'dm':['profile','account','studio','manage','upload','payouts','rewards'].includes(base)?'profile':['library','history'].includes(base)?'home':'home';
 document.querySelectorAll('[data-primary-view]').forEach(a=>{const active=a.dataset.primaryView===(a.closest('.sidebar')&&['library','history'].includes(base)?'library':primary);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 document.querySelectorAll('.nav-link[data-view]:not([data-primary-view])').forEach(a=>{const active=a.getAttribute('href')==='#'+base+(param?'/'+param:'');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
}
function chartTabs(active=''){return `<nav class="tabs" aria-label="차트 종류">${[['','인기 차트'],['karaoke','노래방 차트'],['rising','급상승'],['newcomers','신인'],['releases','최신 음악']].map(([key,label])=>`<a class="tab ${active===key?'active':''}" href="#charts${key?'/'+key:''}" ${active===key?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;}
function libraryTabs(active='likes'){if(['artists','producers'].includes(active))active='following';return `<nav class="tabs" aria-label="보관함 종류">${[['likes','좋아요'],['playlists','플레이리스트'],['history','최근 들은 곡'],['covers','내 커버곡'],['originals','내 제작곡'],['following','팔로잉'],['followers','팔로워']].map(([key,label])=>`<a class="tab ${active===key?'active':''}" href="#library/${key}" ${active===key?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;}
function browsePlaybackActions(tracks,showCount=true){return `<div class="inline-actions playlist-actions"><button class="primary-button" data-play-all ${tracks.length?'':'disabled'}>${icon('play')} 전체 듣기</button><button class="small-button" data-browse-shuffle ${tracks.length?'':'disabled'}>${icon('shuffle')} 섞어 듣기</button>${showCount?`<span class="field-help" data-browse-count>${tracks.length}곡</span>`:''}</div>`;}
function browseQuickLinks(){return `<nav class="browse-shortcuts" aria-label="음악 즐기기"><a href="#charts">${icon('chart')}<strong>인기 차트</strong><small>함께 듣는 음악</small></a><a href="#charts/karaoke">${icon('mic')}<strong>노래방 차트</strong><small>듣고, 직접 부르고</small></a><a href="#community/covers">${icon('users')}<strong>커버곡 둘러보기</strong><small>같은 곡, 다른 목소리</small></a><a href="#collections">${icon('library')}<strong>공개 플레이리스트</strong><small>취향을 나누는 선곡</small></a></nav>`;}
function browseSearchHTML(){return heading('발견','듣고 싶은 곡을 찾고, 기분과 장르로 골라보세요.')+`<form id="search-form" class="aifect-search">${icon('search')}<input name="q" aria-label="곡, 아티스트, 제작자 검색" placeholder="곡, 아티스트, 제작자, 플레이리스트" maxlength="100"><button class="primary-button">검색</button></form>`+section('어떤 음악을 찾고 있나요?')+browseQuickLinks()+section('기분과 활동')+`<div class="genre-chips">${moodOptions.map(([key,label])=>`<a class="genre-chip" href="#discover/mood?m=${key}">${esc(label)}</a>`).join('')}</div>`+section('장르 둘러보기')+`<div class="browse-genres">${genres.filter(g=>g!=='전체').map((g,i)=>`<a style="--genre-tone:${i%5}" href="#discover/genres?g=${encodeURIComponent(g)}"><strong>${esc(g)}</strong>${icon('arrow')}</a>`).join('')}</div>`;}
function karaokeRows(tracks,ranked=false){return tracks.length?`<div class="karaoke-browse-list">${tracks.map((t,i)=>`<article class="karaoke-browse-row">${ranked?`<span class="browse-rank">${t.browseRank||i+1}</span>`:''}<a href="#song/${esc(t.id)}" aria-label="${esc(t.title)} 곡 정보">${cover(t,'mini-cover')}</a><div class="karaoke-browse-info"><a href="#song/${esc(t.id)}"><strong>${esc(t.title)}</strong></a><span>${credits(t)}</span><small>${esc(t.genre)} · ${time(t.duration)} · MR 제공</small>${trackStats(t)}</div><div class="karaoke-browse-actions"><button class="small-button" data-play="${esc(t.id)}" aria-label="${esc(t.title)} 원곡 듣기">${icon('play')} 원곡 듣기</button><a class="text-link" href="#community/rankings?period=all&amp;original_id=${esc(t.id)}">커버 랭킹</a><a class="small-button" href="#sing/${esc(t.id)}">${icon('mic')} 부르기</a><a class="text-link" href="#cover/${esc(t.id)}">녹음 파일 올리기</a></div></article>`).join('')}</div>`:empty('아직 부를 수 있는 곡이 없어요.','MR이 준비되고 원곡자가 커버를 허락한 곡이 여기에 표시돼요.','#community/covers','다른 사람의 커버 둘러보기');}
function communityPeopleStrip(tracks){const seen=new Set(),people=[];for(const t of tracks){const id=t.producer_id,name=t.producer;if(!id||!name||seen.has(id))continue;seen.add(id);people.push({id,name,kind:t.kind,cover_mode:t.cover_mode});if(people.length>=10)break;}return people.length?`<section class="community-people"><div class="community-people-heading"><div><h2>새로운 목소리</h2><p>최근 커버나 신곡을 올린 사람들의 프로필을 만나보세요.</p></div><a href="#following">팔로잉 보기</a></div><div class="community-people-row">${people.map(p=>`<a href="#producer/${esc(p.id)}"><span class="community-person-avatar">${esc(p.name.slice(0,1))}</span><strong>${esc(p.name)}</strong><small>${p.kind==='cover'?(p.cover_mode==='duet'?'듀엣 공개':'커버 공개'):'신곡 공개'}</small></a>`).join('')}</div></section>`:'';}
function communityFeed(tracks){return tracks.length?'<div class="music-feed">'+tracks.map(t=>musicTrackCard(t)).join('')+'</div>':empty('아직 공개된 음악이 없어요.','다른 음악을 둘러보거나 첫 곡을 들려주세요.','#karaoke','부를 곡 찾기');}
async function popularChartView(raw=''){
 const query=new URLSearchParams(raw.includes('?')?raw.split('?')[1]:''),period=query.get('period')||'week';
 const d=await api('/api/catalog?section=tracks&chart=top&period='+encodeURIComponent(period));
 const chart=d.chart,tracks=d.tracks;
 const periods=[['today','오늘'],['week','이번 주'],['month','이달'],['all','명예의 전당']];
 const periodsHTML='<nav class="tabs" aria-label="인기차트 기간">'+periods.map(([key,label])=>'<a class="tab '+(period===key?'active':'')+'" href="#charts?period='+key+'" '+(period===key?'aria-current="page"':'')+'>'+label+'</a>').join('')+'</nav>';
 const criteria='<details class="chart-criteria"><summary>인기점수는 어떻게 계산하나요?</summary><p>재생 50점 · 좋아요 25점 · 댓글 참여 15점 · 선물 10점. 항목별 최다 기록 대비 비율로 환산해 합산합니다. 1골드와 1별은 같은 선물 점수로 계산합니다.</p><p>30초 이상(짧은 곡은 60%) 들은 재생을 계정·곡당 하루 1회 반영합니다. 댓글은 기간 내 참여자당 1회, 삭제한 댓글과 취소한 좋아요는 제외합니다. 본인 활동과 환불된 구매분의 선물도 제외합니다. 기간은 한국 시간 기준이며, 같은 점수는 재생·좋아요·최신 등록순으로 정렬합니다.</p></details>';
 const rows=tracks.map((t,i)=>'<article class="popular-chart-row"><span class="browse-rank">'+(i+1)+'</span><a href="#song/'+esc(t.id)+'" aria-label="'+esc(t.title)+' 곡 정보">'+cover(t,'mini-cover')+'</a><div class="popular-chart-info"><a href="#song/'+esc(t.id)+'"><strong>'+esc(t.title)+'</strong></a><span>'+credits(t)+'</span><small>재생 '+number(t.chart_plays)+' · 좋아요 '+number(t.chart_likes)+' · 댓글 참여 '+number(t.chart_comments)+' · 선물 '+number(t.chart_gifts)+'</small></div><div class="chart-score"><strong>'+Number(t.chart_score).toFixed(2)+'</strong><small>인기점수</small></div><button class="icon-button" data-play="'+esc(t.id)+'" aria-label="'+esc(t.title)+' 듣기">'+icon('play')+'</button></article>').join('');
 return {html:heading('AIFECT 인기차트','함께 듣고, 좋아하고, 응원한 음악의 순위.')+chartTabs()+periodsHTML+criteria+'<p class="field-help">'+esc(chart?.label||'이번 주')+' · 한국 시간 기준 · 최대 100점</p>'+browsePlaybackActions(tracks)+(tracks.length?'<div class="popular-chart-list">'+rows+'</div>':empty('아직 공개된 곡이 없어요.','새로운 음악이 올라오면 여기서 만나요.')),tracks};
}
async function browseView(base,param,raw){
 if(base==='charts'&&(!param||param==='top'))return popularChartView(raw);
 if(base==='search'&&!param)return {html:browseSearchHTML()};
 if(base==='charts'&&param==='karaoke'||base==='karaoke'&&param==='chart'){
  const d=await api('/api/cover-rankings?kind=tracks&period=week&include_unranked=1'),tracks=d.tracks.filter(t=>t.kind==='cover');
  return {html:heading('노래방 차트','공개된 커버곡만 모았어요. 이번 주 받은 좋아요 순으로 만나요.')+chartTabs('karaoke')+browsePlaybackActions(tracks)+(tracks.length?coverRankTracksHTML(tracks):empty('아직 등록된 커버곡이 없어요','첫 커버곡이 공개되면 이곳에서 만날 수 있어요.','#karaoke','노래 부르기')),tracks};
 }
 if(base==='karaoke'&&param==='drafts'){if(!me){returnRoute=location.hash;return {html:gate()};}return {html:karaokeDraftsHTML(await listSingDrafts())};}
 if(base==='karaoke'){
  const ranked=base==='charts'||param==='chart',[d,duets]=await Promise.all([api('/api/karaoke'),api('/api/duets')]),tracks=d.tracks.map((t,i)=>({...t,browseRank:i+1}));
  const title=ranked?'노래방 차트':'부르기',desc=ranked?'부를 수 있는 곡의 원곡 재생·좋아요 기준 순위예요.':'듣기만 하던 음악, 이번에는 내 목소리로.';
  let html=heading(title,desc)+duetLobbyHTML(duets.tracks)+(base==='charts'?chartTabs('karaoke'):`<nav class="sing-shortcuts" aria-label="부르기 바로가기"><a class="tab active" href="#karaoke" aria-current="page">부를 수 있는 곡</a><a class="tab" href="#charts/karaoke">노래방 차트</a><a class="tab" href="#community/covers">커버곡 둘러보기</a><a class="tab" href="#library/covers">내 커버곡</a><a class="tab" href="#community/rankings">${icon('chart')} 커버 랭킹</a><a class="tab" href="#karaoke/drafts">${icon('edit')} 초안</a></nav>`);
  html+=`<section class="singing-intro"><div>${icon('mic')}<div><strong>원곡을 듣고, 나만의 커버를 남겨보세요.</strong><p>사이트에서도 마이크와 이어폰만 준비하면 MR·가사와 함께 녹음할 수 있어요.</p></div></div><a class="text-link" href="#community/covers">커버 감상하기 ${icon('arrow')}</a></section><div class="explorer-toolbar"><input id="karaoke-search" type="search" aria-label="부를 수 있는 곡 검색" placeholder="곡 제목, 아티스트, 제작자로 찾기"><span class="field-help" id="karaoke-count" aria-live="polite">${tracks.length}곡</span></div>${browsePlaybackActions(tracks,false)}<div id="karaoke-results">${karaokeRows(tracks,ranked)}</div>`;
  return {html,tracks,karaokeTracks:tracks,ranked};
 }
 if(base==='community'||base==='covers')return communityView(base,param,raw);
 if(base==='history'||base==='library'&&['history','covers','originals','following'].includes(param)){
  if(!me){returnRoute=location.hash;return {html:gate()};}
  const tab=base==='history'?'history':param;let html=heading('내 보관함','좋아하는 음악과 내가 남긴 목소리를 한곳에서.')+libraryTabs(tab);
  if(tab==='following'){await refreshLibrary();const people=kind=>library.follows.filter(f=>f.kind===kind).map(f=>({...f,id:f.target_id}));html+=`<p class="field-help"><a class="text-link" href="#community/following">팔로우한 창작자의 새 음악 듣기</a></p>`;for(const [kind,title] of [['producer','창작자'],['artist','AI 아티스트']])html+=section(title)+(people(kind).length?peopleListHTML(people(kind),kind):`<p class="empty-inline">아직 팔로우한 ${title}가 없어요. <a class="text-link" href="#${kind==='producer'?'producers':'artists'}">둘러보기</a></p>`);return {html};}
  if(tab==='history'){const d=await api('/api/history');return {html:html+browsePlaybackActions(d.tracks)+list(d.tracks),tracks:d.tracks};}
  const d=await api('/api/studio'),owned=d.tracks.filter(t=>t.kind===(tab==='covers'?'cover':'original')),published=owned.filter(t=>t.status==='published');
  html+=`<div class="inline-actions playlist-actions"><a class="primary-button" href="#${tab==='covers'?'karaoke':'upload'}">${icon('plus')} ${tab==='covers'?'새 커버곡 부르기':'제작곡 올리기'}</a><a class="text-link" href="#studio">스튜디오에서 관리</a></div>`;
  html+=tab==='covers'&&owned.length?coverCollectionHTML(owned,'my-covers',true):owned.length?`<div class="own-music-list">${owned.map(t=>`<article class="own-music-row">${cover(t,'mini-cover')}<div><strong>${esc(t.title)}</strong><small>${esc(({published:'공개 중',draft:'작성 중',processing:'음원 처리 중',hidden:'비공개',failed:'처리 실패'})[t.status]||'준비 중')}</small></div>${t.status==='published'?`<button class="icon-button" data-play="${esc(t.id)}" aria-label="${esc(t.title)} 듣기">${icon('play')}</button>`:''}<a class="small-button" href="#manage/${esc(t.id)}">관리</a></article>`).join('')}</div>`:empty(tab==='covers'?'아직 내 커버곡이 없어요.':'아직 내 제작곡이 없어요.','좋아하는 음악으로 나만의 이야기를 시작해보세요.',tab==='covers'?'#karaoke':'#upload',tab==='covers'?'부를 곡 찾아보기':'음악 올리기');
  return {html,tracks:published};
 }
 return null;
}
function bindBrowse(view){
 bindCommunity(view);
 const search=$('#karaoke-search');if(search)search.oninput=()=>{const q=search.value.trim().toLocaleLowerCase(),items=view.karaokeTracks.filter(t=>[t.title,t.artist,t.producer].join(' ').toLocaleLowerCase().includes(q));routeTracks=items;$('#karaoke-count').textContent=items.length+'곡';document.querySelectorAll('[data-browse-count]').forEach(el=>el.textContent=items.length+'곡');$('#karaoke-results').innerHTML=items.length?karaokeRows(items,view.ranked):'<p class="empty-inline">일치하는 곡이 없어요. 다른 제목이나 창작자 이름을 검색해보세요.</p>';document.querySelectorAll('[data-play-all],[data-browse-shuffle]').forEach(b=>b.disabled=!items.length);};
 const button=$('[data-browse-shuffle]');if(button)button.onclick=async()=>{const tracks=[...routeTracks];for(let i=tracks.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[tracks[i],tracks[j]]=[tracks[j],tracks[i]];}if(tracks.length)try{await play(tracks[0].id,tracks);}catch(e){toast(e.message);}};
}

let homeBrowseObserver=null;
